import signal
import queue
from multiprocessing import Pool

jobs = queue.Queue()
pool = Pool(processes=4)          # built at module import
_shutting_down = False

def on_term(signum, frame):
    global _shutting_down
    _shutting_down = True

signal.signal(signal.SIGTERM, on_term)

def run():
    while True:
        if _shutting_down and jobs.empty():
            break
        try:
            job = jobs.get(timeout=1)
        except queue.Empty:
            continue
        pool.apply_async(handle, (job,))
    # exit without joining outstanding async results

def handle(job):
    return job * 2

if __name__ == "__main__":
    run()
